// Port of SDR++ core/src/dsp/{block.h, processor.h (lines 1-69), sink.h, source.h, operator.h,
// hier_block.h} (@8c9f5ee).
//
// SDR++ runs one thread per block, connected by double-buffered `stream<T>`s, with a
// `run()` generated by DEFAULT_PROC_RUN that calls `process(count, in, out)`. Composite blocks
// already call children's `process()` synchronously. The Dart port keeps only the synchronous
// `process()` contract (docs/02 §1.3, §1.8): the whole graph runs in one DSP isolate, so
// there are no threads, `start/stop`, `tempStop/tempStart`, `ctrlMtx` or `swap/flush`.
// Setters are applied between blocks by the caller.
import 'dart:typed_data';

import 'types.dart';

export 'types.dart';

/// `dsp::Processor<I, O>`: one input, one output.
///
/// [process] reads [count] samples of [inType] from `input` and writes samples of
/// [outType] into `output`, returning the number of output samples. Unless noted otherwise,
/// `input` and `output` may be the same list (in-place), as in the C++ blocks.
/// `output` must be large enough for the produced samples.
abstract class Processor {
  SampleType get inType;
  SampleType get outType;

  int process(int count, Float32List input, Float32List output);

  /// Clears internal state (history, phase, …). No-op for stateless blocks.
  void reset() {}
}

/// Processor with the same input and output type (`Processor<T, T>`), usable in a [Chain].
abstract class ProcessorTT extends Processor {
  SampleType get type;
  @override
  SampleType get inType => type;
  @override
  SampleType get outType => type;
}

/// `dsp::Operator<A, B, O>`: two inputs of equal length, one output.
abstract class Operator {
  int process(int count, Float32List a, Float32List b, Float32List output);
}

/// `dsp::Sink<T>`: input only.
abstract class Sink {
  SampleType get inType;
  void process(int count, Float32List input);
}

/// Grows [buf] (keeping the first [keep] floats) so that it holds at least [minFloats] floats.
/// Allocation happens only when a larger block than ever before arrives; steady state is
/// allocation-free. Returns the (possibly new) buffer, sized for SIMD views
/// (multiple of 4 floats plus padding).
Float32List growBuffer(Float32List buf, int minFloats, int keep) {
  if (buf.length >= minFloats + 8) return buf;
  int len = buf.length < 64 ? 64 : buf.length;
  while (len < minFloats + 8) {
    len = len + (len >> 1);
  }
  len = (len + 3) & ~3;
  final nb = Float32List(len);
  if (keep > 0) nb.setRange(0, keep, buf);
  return nb;
}
